mapper.select:
SELECT usage_date, tenant_id, project_id, model_alias, key_id,
       requests, prompt_tokens, completion_tokens, total_tokens, cost
FROM v_usage_daily
WHERE usage_date >= #{from,jdbcType=DATE}
  AND usage_date <= #{to,jdbcType=DATE}

    AND tenant_id = #{tenantId,jdbcType=VARCHAR}


    AND project_id = #{projectId,jdbcType=VARCHAR}


    AND model_alias = #{modelAlias,jdbcType=VARCHAR}


    AND key_id = #{keyId,jdbcType=VARCHAR}

ORDER BY usage_date ASC, tenant_id ASC, project_id ASC, model_alias ASC

SELECT DISTINCT deployment_model FROM call_logs WHERE created_at >= CAST(#{from,jdbcType=DATE} AS TIMESTAMP) AND created_at < (CAST(#{to,jdbcType=DATE} AS TIMESTAMP) + INTERVAL '1' DAY) AND deployment_model IS NOT NULL AND total_tokens > 0
AND tenant_id = #{tenantId,jdbcType=VARCHAR}
AND project_id = #{projectId,jdbcType=VARCHAR}
ORDER BY deployment_model
